# frozen_string_literal: true

module Jekyll
  module Drops
    class DocumentDrop < Drop
      extend Forwardable

      NESTED_OBJECT_FIELD_BLACKLIST = %w(
        content output excerpt next previous
      ).freeze

      YAML_FILE_EXTS = %w(.yaml .yml).freeze
      SASS_FILE_EXTS = %w(.sass .scss).freeze
      LIQUID_TAG_REGEX = %r!{%-?\s*(\w+)\s*.*?-?%}!m.freeze
      MKDWN_LINK_REF_REGEX = %r!^ {0,3}(?:(\[[^\]]+\])(:.+))$!.freeze
      DATE_FILENAME_MATCHER = %r!^(?>.+/)*?(\d{2,4}-\d{1,2}-\d{1,2})-([^/]*)(\.[^.]+)$!.freeze
      DATELESS_FILENAME_MATCHER = %r!^(?:.+/)*(.*)(\.[^.]+)$!.freeze

      HIDDEN_PUBLIC_METHODS = %w(
        build_document_url generate_url_string compose_destination resolve_permalink_value
        generate_url_from_placeholder_drop generate_url_from_placeholder_hash
        possible_url_keys sanitize_url_string escape_url_path unescape_url_path
        absolute_url_for_site relative_url_for_site year_fragment month_fragment
        day_fragment ensure_leading_slash strip_index_from_url
        carve_excerpt partition_excerpt_content sanctify_excerpt_tags
        collect_markdown_refs excerpt_endtag_regex liquid_block_tag?
        print_excerpt_warning excerpt_liquid_renderable?
        read_document_body merge_default_data ingest_file_content
        handle_read_failure yaml_document? asset_document? sass_document?
        coffeescript_document? liquid_render_allowed? layout_skipped?
        layout_placement_allowed? compose_write! publication_allowed?
        write_permitted? cleaned_path_for output_extension_for source_mtime_for
        draft_document? complete_post_data
        merge_front_matter! merge_category_list! merge_parsed_date!
        fill_title_and_slug fill_categories fill_tags
        categories_from_special_dir modify_inferred_date generate_document_excerpt
        excerpt_separator_value generate_excerpt_configured?
        next_collection_doc previous_collection_doc
        processable_entry? publishable_entry? arrange_collection_docs
        resolve_document_date related_document_list
        determine_docs_sort_order rearrange_docs_by_order
        order_docs_with_warning sort_docs_by_metadata_key
        hour_fragment minute_fragment second_fragment i_day_fragment i_month_fragment
        short_month_fragment long_month_fragment short_year_fragment
        slug_fragment pretty_title_fragment categories_path_fragment
        slugified_categories_fragment name_fragment
        assign_page_payload assign_highlighter_options invalid_layout_assignment?
        permalink_extension_for converter_output_extension_for
        prepare_render_registers render_markup_pipeline
        layout_exists_for? collect_output_extensions
        iso_week_year_fragment iso_week_fragment weekday_fragment
        short_weekday_fragment long_weekday_fragment year_day_fragment
      ).freeze

      mutable false

      delegate_method_as :relative_path, :path
      private delegate_method_as :data, :fallback_data

      delegate_methods :id, :output, :content, :to_s, :relative_path, :url, :date
      data_delegators "title", "categories", "tags"

      def collection
        @obj.collection.label
      end

      def excerpt
        fallback_data["excerpt"].to_s
      end

      def <=>(other)
        return nil unless other.is_a? DocumentDrop

        cmp = self["date"] <=> other["date"]
        cmp = self["path"] <=> other["path"] if cmp.nil? || cmp.zero?
        cmp
      end

      def previous
        @obj.previous_doc.to_liquid
      end

      def next
        @obj.next_doc.to_liquid
      end

      # Generate a Hash for use in generating JSON.
      # This is useful if fields need to be cleared before the JSON can generate.
      #
      # state - the JSON::State object which determines the state of current processing.
      #
      # Returns a Hash ready for JSON generation.
      def hash_for_json(state = nil)
        to_h.tap do |hash|
          if state && state.depth >= 2
            hash["previous"] = collapse_document(hash["previous"]) if hash["previous"]
            hash["next"]     = collapse_document(hash["next"]) if hash["next"]
          end
        end
      end

      # Generate a Hash which breaks the recursive chain.
      # Certain fields which are normally available are omitted.
      #
      # Returns a Hash with only non-recursive fields present.
      def collapse_document(doc)
        doc.keys.each_with_object({}) do |(key, _), result|
          result[key] = doc[key] unless NESTED_OBJECT_FIELD_BLACKLIST.include?(key)
        end
      end

      def self.invokable_methods
        @invokable_methods ||= super.dup.subtract(HIDDEN_PUBLIC_METHODS)
      end

      def content_methods
        @content_methods ||= super - HIDDEN_PUBLIC_METHODS
      end

      def key?(key)
        return false if key.nil?
        return true if self.class.mutable? && mutations.key?(key)
        if HIDDEN_PUBLIC_METHODS.include?(key.to_s)
          return fallback_data.key?(key)
        end

        respond_to?(key) || fallback_data.key?(key)
      end


      def build_document_url(template, placeholders, permalink)
        @url_bundle ||= {}
        @url_bundle[:template] = template
        @url_bundle[:placeholders] = placeholders
        @url_bundle[:permalink] = permalink
        if @url_bundle[:template].nil? && @url_bundle[:permalink].nil?
          raise ArgumentError, "One of :template or :permalink must be supplied."
        end

        generated = if @url_bundle[:permalink]
                      generate_url_string(@url_bundle[:permalink], @url_bundle[:placeholders])
                    else
                      generate_url_string(@url_bundle[:template], @url_bundle[:placeholders])
                    end
        sanitize_url_string(generated)
      end

      def generate_url_string(template, placeholders)
        @url_bundle ||= {}
        @url_bundle[:active_template] = template
        @url_bundle[:active_placeholders] = placeholders
        if @url_bundle[:active_template].nil?
          return ""
        elsif @url_bundle[:active_placeholders].is_a?(Drops::UrlDrop)
          generate_url_from_placeholder_drop(
            @url_bundle[:active_template],
            @url_bundle[:active_placeholders]
          )
        else
          generate_url_from_placeholder_hash(
            @url_bundle[:active_template],
            @url_bundle[:active_placeholders]
          )
        end
      end

      def generate_url_from_placeholder_drop(template, placeholders)
        @url_bundle ||= {}
        @url_bundle[:drop_template] = template
        @url_bundle[:drop_placeholders] = placeholders
        @url_bundle[:drop_template].to_s.gsub(%r!:([a-z_]+)!) do |match|
          name = Regexp.last_match(1)
          pool = possible_url_keys(name)
          winner = pool.find { |key| @url_bundle[:drop_placeholders].key?(key) }
          if winner.nil?
            raise NoMethodError,
                  "The URL template doesn't have #{pool.join(" or ")} keys. "\
                  "Check your permalink template!"
          end

          value = @url_bundle[:drop_placeholders][winner]
          value = "" if value.nil?
          replacement = escape_url_path(value)
          match.sub(":#{winner}", replacement)
        end
      end

      def generate_url_from_placeholder_hash(template, placeholders)
        @url_bundle ||= {}
        @url_bundle[:hash_template] = template.to_s
        @url_bundle[:hash_placeholders] = placeholders || {}
        @url_bundle[:hash_placeholders].inject(@url_bundle[:hash_template]) do |result, token|
          break result if result.index(":").nil?

          if token.last.nil?
            result.gsub("/:#{token.first}", "")
          else
            result.gsub(":#{token.first}", escape_url_path(token.last))
          end
        end
      end

      def possible_url_keys(key)
        @url_bundle ||= {}
        @url_bundle[:key_probe] = key.to_s
        if @url_bundle[:key_probe].end_with?("_")
          [@url_bundle[:key_probe], @url_bundle[:key_probe].chomp("_")]
        else
          [@url_bundle[:key_probe]]
        end
      end

      def sanitize_url_string(str)
        @url_bundle ||= {}
        @url_bundle[:raw_url] = str.to_s
        "/#{@url_bundle[:raw_url]}".gsub("..", "/").tap do |result|
          result.gsub!("./", "")
          result.squeeze!("/")
        end
      end

      def escape_url_path(path)
        @url_bundle ||= {}
        @url_bundle[:escape_input] = path.to_s
        return @url_bundle[:escape_input] if @url_bundle[:escape_input].empty?
        return @url_bundle[:escape_input] if %r!^[a-zA-Z0-9./-]+$!.match?(@url_bundle[:escape_input])

        Addressable::URI.encode(@url_bundle[:escape_input]).encode("utf-8").sub("#", "%23")
      end

      def unescape_url_path(path)
        @url_bundle ||= {}
        @url_bundle[:unescape_input] = path.to_s.encode("utf-8")
        return @url_bundle[:unescape_input] unless @url_bundle[:unescape_input].include?("%")

        Addressable::URI.unencode(@url_bundle[:unescape_input])
      end

      def compose_destination(base_directory, document_url, site, output_ext)
        @url_bundle ||= {}

